import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const SUPABASE_URL='https://apugxrwhiyvwcrpzvgxj.supabase.co';
const SUPABASE_KEY='sb_publishable_WoZaQe5QeUDLb764uMWEtw_78rsp8Mi';
const EDGE=`${SUPABASE_URL}/functions/v1`;
const APP_VERSION='0.7.0';
const sb=createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const root=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const fmt=v=>v?new Date(v).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:String(v).includes('T')?'short':undefined}):'—';
const qs=new URLSearchParams(location.search);
let invitationToken=qs.get('token')||sessionStorage.getItem('isssc_invite_token')||'';
if(qs.get('token'))sessionStorage.setItem('isssc_invite_token',qs.get('token'));
if(qs.get('token'))history.replaceState({},'',location.pathname+'#register');
let session=null,profile=null,eventData=null,eventFeedAccess='public',activeStaffTab='overview',eventRefreshTimer=null;

function shell(content,{active='home'}={}){
  return `<header class="top"><div class="wrap"><div class="brand"><div class="mark">❄</div><div>UKAF WSA<small>ISSSC 2027 · Méribel</small></div></div><nav class="nav"><button data-route="home" class="${active==='home'?'active':''}">Home</button><button data-route="event" class="${active==='event'?'active':''}">Event app</button><button data-route="register" class="${active==='register'?'active':''}">Registration</button><button data-route="mytrip" class="${active==='mytrip'?'active':''}">My trip</button><button data-route="staff" class="login ${active==='staff'?'active':''}">${session?'Staff':'Staff sign in'}</button></nav></div></header>${content}<footer class="footer"><div class="wrap"><strong>UK Armed Forces Winter Sports Association</strong><div>ISSSC 2027 · Attendance · Event information · Protocol · Sponsorship · Billing</div><div class="meta footerlinks"><a href="/privacy.html">Privacy</a><span>Version ${APP_VERSION}</span></div></div></footer>`;
}

function bindRoutes(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>navigate(b.dataset.route));}
function navigate(route){if(route!=='event'&&eventRefreshTimer){clearInterval(eventRefreshTimer);eventRefreshTimer=null}const url=route==='register'&&invitationToken?`/?token=${encodeURIComponent(invitationToken)}#register`:'/#'+route;history.replaceState({},'',url);render(route);}

function renderHome(){
 root.innerHTML=shell(`<main><section class="hero"><div class="wrap"><div class="kicker">30 January – 6 February 2027 · Méribel</div><h1>Inter Service<br><em>Snow Sports Championships</em></h1><p>A secure event platform for attendance, live event information, race locations, table plans, biographies, sponsorship, Protocol and billing.</p><div class="actions"><button class="btn primary" data-route="event">Open event app</button><button class="btn ghost" data-route="register">Attendee registration</button></div></div></section><div class="wrap live"><div class="livebar"><div><small>Event</small><strong>ISSSC 2027</strong></div><div><small>Full week</small><strong>30 Jan – 6 Feb</strong></div><div><small>Changeover</small><strong>3 Feb</strong></div><div><small>Location</small><strong>Méribel, France</strong></div></div></div><section class="section"><div class="wrap"><div class="kicker" style="color:#0a78ae">Attendee experience</div><h2>Everything for the week, in one place.</h2><p class="lead">The app becomes the current source for event information, replacing multiple emailed versions and ad-hoc updates.</p><div class="grid three" style="margin-top:22px"><div class="card"><div class="icon">📅</div><h3>Live programme</h3><p>Race schedules, ceremonies, dinners and timings.</p></div><div class="card"><div class="icon">📍</div><h3>Race locations</h3><p>Current venue, directions and changes.</p></div><div class="card"><div class="icon">📣</div><h3>Event updates</h3><p>Priority notices from the event team.</p></div><div class="card"><div class="icon">🍽️</div><h3>Table plans</h3><p>Current seating and table information.</p></div><div class="card"><div class="icon">👤</div><h3>People</h3><p>VIP, sponsor and event-team biographies.</p></div><div class="card"><div class="icon">📄</div><h3>Documents</h3><p>Guides and useful event information.</p></div></div></div></section></main>`,{active:'home'});bindRoutes();
}

async function loadEventFeed(){
  if(session?.access_token){
    try{
      const r=await fetch(`${EDGE}/attendee-event-feed?t=${Date.now()}`,{cache:'no-store',headers:{'Authorization':`Bearer ${session.access_token}`}});
      const d=await r.json();
      if(r.ok){eventFeedAccess='attendee';return d;}
    }catch{}
  }
  const r=await fetch(`${EDGE}/event-feed?year=2027&t=${Date.now()}`,{cache:'no-store'});
  const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to load event');eventFeedAccess='public';return d;
}
async function renderEvent(){
 root.innerHTML=shell(`<section class="section"><div class="wrap"><div class="kicker" style="color:#0a78ae">ISSSC event app</div><h2>Live event information</h2><p class="lead">Public information is available to everyone. Signed-in attendees also see attendee-only documents, table plans and their own seating.</p><div id="eventAccess"></div><div class="tabs"><button class="tab active" data-tab="updates">Updates</button><button class="tab" data-tab="schedule">Programme</button><button class="tab" data-tab="venues">Locations</button><button class="tab" data-tab="people">People</button><button class="tab" data-tab="tables">Table plans</button><button class="tab" data-tab="docs">Documents</button><button class="tab" data-tab="sponsors">Sponsors</button></div><div id="eventBody" class="loading">Loading event information…</div></div></section>`,{active:'event'});bindRoutes();
 try{eventData=await loadEventFeed();renderEventPanels();if(eventRefreshTimer)clearInterval(eventRefreshTimer);eventRefreshTimer=setInterval(async()=>{if(!location.hash.includes('event'))return;try{eventData=await loadEventFeed();renderEventPanels();}catch{}},60000);}catch(e){document.querySelector('#eventBody').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}
}

function renderEventPanels(){
  const d=eventData||{};
  const access=document.querySelector('#eventAccess');
  if(access)access.innerHTML=eventFeedAccess==='attendee'
    ?`<div class="notice ok"><b>Attendee view</b> · Signed in${d.attendee?` as ${esc(d.attendee.first_name)} ${esc(d.attendee.surname)}`:''}. Attendee-only information is unlocked.</div>`
    :`<div class="notice"><b>Public view.</b> Table plans, personal seating and attendee-only documents require sign-in. <button class="btn small secondary" data-route="mytrip">Sign in / My trip</button></div>`;
  bindRoutes();
  const updates=d.announcements?.length?`<div class="feed">${d.announcements.map(a=>`<div class="card"><div class="icon">📣</div><div><span class="pill ${a.priority==='urgent'?'red':''}">${esc(a.priority)}</span><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p>${a.action_url?`<p><a target="_blank" rel="noopener" href="${esc(a.action_url)}">${esc(a.action_label||'Open')}</a></p>`:''}<div class="meta">${fmt(a.publish_at)}</div></div></div>`).join('')}</div>`:`<div class="empty">No event updates have been published yet.</div>`;
  const schedule=d.schedule?.length?`<div class="feed">${d.schedule.map(x=>`<div class="card"><div class="datebox"><b>${new Date(x.starts_at).toLocaleDateString('en-GB',{day:'2-digit'})}</b>${new Date(x.starts_at).toLocaleDateString('en-GB',{month:'short'})}</div><div><span class="pill">${esc(x.category||'event')}</span><h3>${esc(x.title)}</h3><p>${esc(x.description||'')}</p>${x.attendee_notes?`<p><b>Attendee note:</b> ${esc(x.attendee_notes)}</p>`:''}<div class="meta">${fmt(x.starts_at)}</div>${x.live_results_url?`<a target="_blank" rel="noopener" href="${esc(x.live_results_url)}">Live results</a>`:''}${x.stream_url?` · <a target="_blank" rel="noopener" href="${esc(x.stream_url)}">Watch</a>`:''}</div></div>`).join('')}</div>`:`<div class="empty">The programme will appear here when published.</div>`;
  const venues=d.venues?.length?`<div class="grid two">${d.venues.map(v=>`<div class="card"><div class="icon">📍</div><h3>${esc(v.name)}</h3><p>${esc(v.directions_text||v.address||'Location details to follow.')}</p>${v.map_url?`<p><a target="_blank" rel="noopener" href="${esc(v.map_url)}">Open map</a></p>`:''}</div>`).join('')}</div>`:`<div class="empty">Race and event locations will appear here when published.</div>`;
  const people=d.biographies?.length?`<div class="people">${d.biographies.map(p=>`<div class="card person"><div class="photo">${p.photo_path?`<img src="${esc(p.photo_path)}" alt="">`:esc((p.display_name||'?').slice(0,1))}</div><h3>${esc(p.display_name)}</h3><div class="meta">${esc(p.role_title||'')}${p.organisation_name?' · '+esc(p.organisation_name):''}</div><p>${esc(p.biography||'')}</p></div>`).join('')}</div>`:`<div class="empty">Biographies will appear here once published.</div>`;
  const plans=d.table_plans||[];const seats=d.seating_assignments||[];
  const tables=eventFeedAccess!=='attendee'?'<div class="notice">Sign in to My trip to view attendee table plans and your personal seating assignment.</div>':`${plans.length?plans.map(p=>`<div class="card" style="margin-bottom:12px"><span class="pill">Version ${esc(p.version)}</span><h3>${esc(p.title)}</h3><p>${esc(p.notes||'')}</p>${p.href?`<p><a target="_blank" rel="noopener" href="${esc(p.href)}">Open table plan</a></p>`:''}</div>`).join(''):'<div class="empty">No attendee table plans have been published yet.</div>'}${seats.length?`<h3 style="margin-top:22px">Your seating</h3><div class="grid two">${seats.map(x=>`<div class="card"><h3>${esc(x.seating_tables?.schedule_items?.title||'Seating')}</h3><p><b>${esc(x.seating_tables?.table_name||'Table')}</b>${x.seat_label?` · ${esc(x.seat_label)}`:''}</p><div class="meta">${fmt(x.seating_tables?.schedule_items?.starts_at)}</div></div>`).join('')}</div>`:'<div class="empty" style="margin-top:14px">No published seating assignment is linked to you yet.</div>'}`;
  const docs=d.documents?.length?`<div class="card">${d.documents.map(x=>{const href=x.href||x.external_url||x.file_path;return `<div class="doc"><div><b>${esc(x.title)}</b><div class="meta">${esc(x.category||'Document')}</div></div>${href?`<a target="_blank" rel="noopener" href="${esc(href)}">Open</a>`:''}</div>`}).join('')}</div>`:`<div class="empty">No documents are currently available in this view.</div>`;
  const sponsors=d.sponsors?.length?`<div class="grid three">${d.sponsors.map(s=>`<div class="card sponsorcard">${s.organisations?.logo_path?`<img class="sponsorlogo" src="${esc(s.organisations.logo_path)}" alt="">`:''}<span class="pill">${esc(s.sponsor_tier||'Sponsor')}</span><h3>${esc(s.organisations?.organisation_name||'Sponsor')}</h3>${s.race_funding_sponsor?'<p><b>Race funding sponsor</b></p>':''}${s.organisations?.website_url?`<p><a target="_blank" rel="noopener" href="${esc(s.organisations.website_url)}">Website</a></p>`:''}</div>`).join('')}</div>`:`<div class="empty">Sponsor information will appear here when published.</div>`;
  document.querySelector('#eventBody').innerHTML=`<div id="updates" class="panel active">${updates}</div><div id="schedule" class="panel">${schedule}</div><div id="venues" class="panel">${venues}</div><div id="people" class="panel">${people}</div><div id="tables" class="panel">${tables}</div><div id="docs" class="panel">${docs}</div><div id="sponsors" class="panel">${sponsors}</div>`;
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#'+b.dataset.tab).classList.add('active');});
}

async function renderRegister(){
 root.innerHTML=shell(`<section class="section"><div class="wrap" style="max-width:920px"><div class="kicker" style="color:#0a78ae">ISSSC 2027</div><h2>Attendance request</h2><p class="lead">Your form records what you are requesting. Protocol will confirm the operational record after review.</p><div id="registerBody" class="loading">Checking invitation…</div></div></section>`,{active:'register'});bindRoutes();
 if(!invitationToken){document.querySelector('#registerBody').innerHTML='<div class="notice warn"><b>Personal invitation required.</b><br>Registration is opened from the unique invitation link sent by the ISSSC team.</div>';return;}
 try{const r=await fetch(`${EDGE}/invite-lookup?token=${encodeURIComponent(invitationToken)}`);const d=await r.json();if(!r.ok)throw Error(d.error||'Invitation unavailable');registrationForm(d.invitation);}catch(e){document.querySelector('#registerBody').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}
}
function registrationForm(inv){const n=(inv.name||'').trim().split(/\s+/);const first=n.shift()||'';const surname=n.join(' ');document.querySelector('#registerBody').innerHTML=`<div class="notice"><b>${esc(inv.name||'Your invitation')}</b><br>${esc(inv.organisation?.organisation_name||'')} · ${esc(inv.category||'')}<br><span class="meta">Invitation email: ${esc(inv.email)}</span></div><form id="regForm" class="formcard"><div class="formgrid"><div class="sectiontitle"><h3>Your details</h3></div><label class="field"><span>Category</span><input name="category" value="${esc(inv.category||'')}" readonly></label><label class="field"><span>Rank / title</span><input name="title_rank"></label><label class="field"><span>First name *</span><input name="first_name" value="${esc(first)}" required></label><label class="field"><span>Surname *</span><input name="surname" value="${esc(surname)}" required></label><label class="field"><span>Post nominals</span><input name="post_nominals"></label><label class="field"><span>Email *</span><input type="email" name="email" value="${esc(inv.email||'')}" readonly required></label><label class="field"><span>Mobile</span><input name="mobile"></label><label class="field"><span>Date of birth</span><input name="date_of_birth" type="date"></label><label class="field"><span>Service</span><select name="service"><option value="">Select</option><option>Royal Navy</option><option>Army</option><option>Royal Air Force</option><option>Civilian</option><option>Industry</option><option>Other</option></select></label><label class="field"><span>Role / appointment</span><input name="position_role"></label><label class="field"><span>Discipline</span><input name="discipline"></label><label class="check"><input name="submitted_on_behalf" type="checkbox"> I am completing this form for someone else</label><label class="field"><span>Submitter name</span><input name="submitter_name"></label><label class="field"><span>Submitter email</span><input name="submitter_email" type="email"></label><label class="field wide"><span>Dietary requirements</span><textarea name="dietary_requirements"></textarea></label><div class="sectiontitle"><h3>Accommodation</h3><p>Preferences only; final allocation is made by Protocol.</p></div><label class="check"><input name="accommodation_required" type="checkbox" checked> I require accommodation</label><label class="field"><span>Hotel preference</span><select name="hotel_preference"><option value="">No preference</option><option>Hotel Eterlou</option><option>Hotel La Chaudanne</option><option>Hotel Le Savoy</option><option>Chalet</option><option>Own accommodation</option></select></label><label class="field"><span>Accommodation from</span><input name="accommodation_from" type="date"></label><label class="field"><span>Accommodation to</span><input name="accommodation_to" type="date"></label><label class="check"><input name="room_share_requested" type="checkbox"> I expect to share a room</label><label class="field"><span>Share with</span><input name="room_share_with"></label><label class="check"><input name="dinners_with_guests" type="checkbox" checked> Dinners with guest group</label><div class="sectiontitle"><h3>Arrival</h3></div><label class="field"><span>Method</span><input name="arrival_method" placeholder="Flight, train, car…"></label><label class="field"><span>Airport / station</span><input name="arrival_airport_station"></label><label class="field"><span>Flight / travel number</span><input name="arrival_flight_number"></label><label class="field"><span>Arrival date & time</span><input name="arrival_datetime" type="datetime-local"></label><label class="check"><input name="arrival_transfer_requested" type="checkbox"> UKAFWSA transfer requested</label><label class="field wide"><span>Arrival details</span><textarea name="arrival_details"></textarea></label><div class="sectiontitle"><h3>Departure</h3></div><label class="field"><span>Method</span><input name="departure_method"></label><label class="field"><span>Airport / station</span><input name="departure_airport_station"></label><label class="field"><span>Flight / travel number</span><input name="departure_flight_number"></label><label class="field"><span>Departure date & time</span><input name="departure_datetime" type="datetime-local"></label><label class="check"><input name="departure_transfer_requested" type="checkbox"> UKAFWSA transfer requested</label><label class="field wide"><span>Departure details</span><textarea name="departure_details"></textarea></label><div class="sectiontitle"><h3>Skiing / snowboarding</h3></div><label class="check"><input name="lift_pass_required" type="checkbox"> 3 Valleys lift pass required</label><label class="field"><span>First ski day</span><input name="first_ski_day" type="date"></label><label class="field"><span>Last ski day</span><input name="last_ski_day" type="date"></label><label class="check"><input name="carre_neige_requested" type="checkbox" checked> Carre Neige required</label><label class="check"><input name="lessons_required" type="checkbox"> Lessons required</label><label class="field"><span>Lesson type</span><select name="lesson_type"><option value="">Select</option><option>Group</option><option>Private</option><option>Telemark</option></select></label><label class="field wide"><span>Lesson dates</span><input name="lesson_dates" placeholder="2027-02-01, 2027-02-02"></label><label class="check"><input name="equipment_hire_required" type="checkbox"> Equipment hire required</label><label class="field"><span>Boot size</span><input name="boot_size"></label><label class="field wide"><span>Anything else Protocol should know?</span><textarea name="other_information"></textarea></label><div class="sectiontitle"><h3>Privacy</h3><p>We only use this information to administer ISSSC attendance, event operations and billing.</p></div><label class="check wide"><input name="privacy_acknowledged" type="checkbox" required> I have read the <a href="/privacy.html" target="_blank" rel="noopener">ISSSC privacy notice</a> and acknowledge how my information will be used.</label></div><div id="regMsg"></div><div class="actions" style="justify-content:flex-end"><button class="btn primary" type="submit">Submit attendance request</button></div></form>`;
 document.querySelector('#regForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const booking=Object.fromEntries(fd.entries());e.currentTarget.querySelectorAll('input[type=checkbox]').forEach(x=>booking[x.name]=x.checked);const button=e.submitter;button.disabled=true;button.textContent='Submitting…';try{const r=await fetch(`${EDGE}/booking-submit`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:invitationToken,booking})});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to submit');document.querySelector('#regMsg').innerHTML=`<div class="notice ok"><b>Attendance request submitted.</b><br>Protocol will review and confirm the operational details.<br><span class="meta">Reference: ${esc(d.booking.public_reference)}</span></div>`;button.textContent='Submitted';}catch(err){document.querySelector('#regMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;button.disabled=false;button.textContent='Submit attendance request';}};
}

async function renderMyTrip(){
  root.innerHTML=shell(`<section class="section"><div class="wrap" style="max-width:980px"><div class="kicker" style="color:#0a78ae">Personal event information</div><h2>My trip</h2><p class="lead">Your confirmed accommodation, travel, lift pass, seating and issued invoices.</p><div id="tripBody" class="loading">Loading your event record…</div></div></section>`,{active:'mytrip'});bindRoutes();
  if(!session){myTripLogin();return}
  await loadProfile();
  const body=document.querySelector('#tripBody');
  if(!profile?.attendee_id){
    const {data:pending}=await sb.from('booking_requests').select('public_reference,status,submitted_at,first_name,surname,category').eq('user_id',session.user.id).order('submitted_at',{ascending:false}).limit(1).maybeSingle();
    body.innerHTML=pending?`<div class="notice warn"><b>${esc(pending.first_name)} ${esc(pending.surname)}</b><br>Your attendance request is currently <b>${esc(pending.status)}</b>. Protocol will confirm the operational record after review.<br><span class="meta">Reference: ${esc(pending.public_reference)} · submitted ${fmt(pending.submitted_at)}</span></div><button id="tripLogout" class="btn secondary">Sign out</button>`:`<div class="notice warn"><b>No attendee record is linked to this account yet.</b><br>Use the same email address as your ISSSC attendance request. If you have only just submitted, sign out and use the link again after Protocol review.</div><button id="tripLogout" class="btn secondary">Sign out</button>`;
    document.querySelector('#tripLogout').onclick=logout;return
  }
  const {data:a,error}=await sb.from('attendees').select('id,first_name,surname,category,attendance_status,stay_charge_periods(id,requested_location,actual_check_in,actual_check_out,billing_from,billing_to,package_type,protocol_confirmed,accommodation_locations(name),room_types(name)),lift_passes(id,required,start_date,end_date,carre_neige_required,protocol_confirmed),travel_records(id,direction,method_of_transport,airport_station,flight_travel_number,travel_datetime,resort_datetime,transfer_requested,transfer_service,protocol_confirmed),invoices(id,invoice_reference,status,gross_total,due_date,payment_link),seating_assignments(seat_label,seating_tables(table_name,published,schedule_items(title,starts_at)))').eq('id',profile.attendee_id).single();
  if(error){body.innerHTML=`<div class="notice error">${esc(error.message)}</div>`;return}
  const stays=a.stay_charge_periods||[], lift=(a.lift_passes||[])[0], arr=(a.travel_records||[]).find(x=>x.direction==='arrival'), dep=(a.travel_records||[]).find(x=>x.direction==='departure'), invoices=a.invoices||[], seats=a.seating_assignments||[];
  const stayHtml=stays.length?stays.map(st=>`<div class="card"><div class="rowbetween"><h3>${esc(st.accommodation_locations?.name||st.requested_location||'Accommodation')}</h3>${st.protocol_confirmed?'<span class="pill green">Confirmed</span>':'<span class="pill amber">Pending</span>'}</div><p>${esc(st.room_types?.name||'Room type to follow')}</p><div class="meta">${esc(st.actual_check_in||st.billing_from||'—')} → ${esc(st.actual_check_out||st.billing_to||'—')}${st.package_type?` · ${esc(st.package_type.replaceAll('_',' '))}`:''}</div></div>`).join(''):'<div class="empty">No accommodation is recorded.</div>';
  const tripCard=(title,t)=>t?`<div class="card"><div class="rowbetween"><h3>${title}</h3>${t.protocol_confirmed?'<span class="pill green">Confirmed</span>':'<span class="pill amber">Pending</span>'}</div><p>${esc(t.method_of_transport||'Travel details')} ${t.flight_travel_number?`· ${esc(t.flight_travel_number)}`:''}</p><div class="meta">${esc(t.airport_station||'')} ${t.travel_datetime?`· ${fmt(t.travel_datetime)}`:''}</div>${t.transfer_requested?`<p>Transfer: ${esc(t.transfer_service||'requested')}</p>`:''}</div>`:`<div class="empty">${title} details are not recorded.</div>`;
  const liftHtml=lift?`<div class="card"><div class="rowbetween"><h3>Lift pass</h3>${lift.protocol_confirmed?'<span class="pill green">Confirmed</span>':'<span class="pill amber">Pending</span>'}</div><p>${lift.required?'3 Valleys pass':'No lift pass required'}</p>${lift.required?`<div class="meta">${esc(lift.start_date||'—')} → ${esc(lift.end_date||'—')} · Carre Neige ${lift.carre_neige_required?'included':'not requested'}</div>`:''}</div>`:'<div class="empty">No lift-pass record is linked.</div>';
  const seatHtml=seats.length?`<div class="grid two">${seats.map(x=>`<div class="card"><h3>${esc(x.seating_tables?.schedule_items?.title||'Seating')}</h3><p>${esc(x.seating_tables?.table_name||'Table TBC')}${x.seat_label?` · ${esc(x.seat_label)}`:''}</p><div class="meta">${fmt(x.seating_tables?.schedule_items?.starts_at)}</div></div>`).join('')}</div>`:'<div class="empty">No published seating assignments yet.</div>';
  const invHtml=invoices.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Reference</th><th>Status</th><th>Total</th><th>Due</th><th></th></tr></thead><tbody>${invoices.map(i=>`<tr><td>${esc(i.invoice_reference)}</td><td><span class="pill">${esc(i.status)}</span></td><td>£${Number(i.gross_total||0).toFixed(2)}</td><td>${esc(i.due_date||'—')}</td><td>${i.payment_link?`<a class="btn small primary" target="_blank" rel="noopener" href="${esc(i.payment_link)}">Pay</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No issued invoices are available.</div>';
  body.innerHTML=`<div class="notice ok"><b>${esc(a.first_name)} ${esc(a.surname)}</b><br>${esc(a.category||'Attendee')} · ${esc(a.attendance_status||'expected')}</div><h3>Accommodation</h3><div class="grid two">${stayHtml}</div><h3 style="margin-top:26px">Travel</h3><div class="grid two">${tripCard('Arrival',arr)}${tripCard('Departure',dep)}</div><h3 style="margin-top:26px">Skiing / snowboarding</h3>${liftHtml}<h3 style="margin-top:26px">Seating</h3>${seatHtml}<h3 style="margin-top:26px">Invoices</h3>${invHtml}<h3 style="margin-top:26px">Event notifications</h3><div id="notificationPanel" class="loading">Checking notification status…</div><div class="actions"><button id="tripLogout" class="btn secondary">Sign out</button></div>`;
  document.querySelector('#tripLogout').onclick=logout;renderNotificationPanel();
}
function myTripLogin(){document.querySelector('#tripBody').innerHTML=`<div class="formcard" style="max-width:560px;margin:auto"><div class="kicker" style="color:#0a78ae">Secure attendee access</div><h2>Sign in to My trip</h2><p class="lead">Use the same email address as your ISSSC attendance request. We will send a passwordless sign-in link.</p><form id="tripLoginForm"><label class="field"><span>Email</span><input name="email" type="email" required></label><div id="tripLoginMsg"></div><div class="actions"><button class="btn primary" type="submit">Send sign-in link</button></div></form></div>`;document.querySelector('#tripLoginForm').onsubmit=async e=>{e.preventDefault();const email=new FormData(e.currentTarget).get('email');const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+'/#mytrip'}});document.querySelector('#tripLoginMsg').innerHTML=error?`<div class="notice error">${esc(error.message)}</div>`:'<div class="notice ok">Sign-in link sent. Check your email and return here.</div>';};}

async function loadProfile(){if(!session?.user){profile=null;return null}const {data}=await sb.from('profiles').select('*').eq('id',session.user.id).maybeSingle();profile=data;return data;}
function urlBase64ToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4);const base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)));}
function pushSupported(){return 'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;}
async function getPushSubscription(){if(!pushSupported())return null;const reg=await navigator.serviceWorker.ready;return reg.pushManager.getSubscription();}
async function enableNotifications(){
  if(!session?.user)throw Error('Sign in before enabling notifications.');
  if(!pushSupported())throw Error('Push notifications are not supported by this browser.');
  const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notification permission was not granted.');
  const cfgRes=await fetch(`${EDGE}/push-public-config`,{cache:'no-store'});const cfg=await cfgRes.json();if(!cfgRes.ok||!cfg.enabled||!cfg.vapid_public_key)throw Error('Event notifications are not available yet.');
  const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();
  if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(cfg.vapid_public_key)});
  const j=sub.toJSON();const {error}=await sb.from('push_subscriptions').upsert({user_id:session.user.id,endpoint:sub.endpoint,p256dh:j.keys?.p256dh||'',auth_key:j.keys?.auth||'',user_agent:navigator.userAgent,active:true,updated_at:new Date().toISOString()},{onConflict:'endpoint'});if(error)throw error;
  return sub;
}
async function disableNotifications(){const sub=await getPushSubscription();if(!sub)return;const {error}=await sb.from('push_subscriptions').update({active:false,updated_at:new Date().toISOString()}).eq('user_id',session.user.id).eq('endpoint',sub.endpoint);if(error)throw error;await sub.unsubscribe();}
async function renderNotificationPanel(){
  const el=document.querySelector('#notificationPanel');if(!el)return;
  if(!pushSupported()){el.innerHTML='<div class="empty">Push notifications are not supported on this browser. You can still use the live Event app.</div>';return;}
  if(Notification.permission==='denied'){el.innerHTML='<div class="notice warn">Notifications are blocked in your browser settings. Re-enable them for this site if you want urgent ISSSC updates.</div>';return;}
  try{const sub=await getPushSubscription();if(sub){el.innerHTML='<div class="card"><div class="rowbetween"><div><h3>Event notifications enabled</h3><p>Urgent or selected event updates can appear on this device.</p></div><span class="pill green">On</span></div><button id="disablePush" class="btn small secondary">Turn off notifications</button></div>';document.querySelector('#disablePush').onclick=async e=>{e.currentTarget.disabled=true;try{await disableNotifications();renderNotificationPanel()}catch(err){alert(err.message);e.currentTarget.disabled=false}};}else{el.innerHTML='<div class="card"><h3>Get event notifications</h3><p>Opt in to selected ISSSC announcements on this device. You can turn them off at any time.</p><button id="enablePush" class="btn small primary">Enable notifications</button></div>';document.querySelector('#enablePush').onclick=async e=>{e.currentTarget.disabled=true;try{await enableNotifications();renderNotificationPanel()}catch(err){alert(err.message);e.currentTarget.disabled=false}};}}catch(err){el.innerHTML=`<div class="notice error">${esc(err.message||'Unable to check notification status')}</div>`;}
}
async function sendPushAnnouncement(announcementId){
  const {data:{session:s}}=await sb.auth.getSession();if(!s)throw Error('Your session has expired. Please sign in again.');
  const r=await fetch(`${EDGE}/send-push-announcement`,{method:'POST',headers:{'content-type':'application/json','Authorization':`Bearer ${s.access_token}`},body:JSON.stringify({announcement_id:announcementId})});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to send push notification');return d;
}
async function renderStaff(){
 root.innerHTML=shell(`<section class="section"><div class="wrap"><div id="staffBody" class="loading">Loading staff workspace…</div></div></section>`,{active:'staff'});bindRoutes();
 if(!session){staffLogin();return}await loadProfile();if(!profile){document.querySelector('#staffBody').innerHTML=`<div class="notice warn"><b>Account created, role not yet assigned.</b><br>Your sign-in is working. An ISSSC administrator must assign your staff role before this workspace opens.</div><button id="logout" class="btn secondary">Sign out</button>`;document.querySelector('#logout').onclick=logout;return}if(!profile.active){document.querySelector('#staffBody').innerHTML='<div class="notice error">This staff account is inactive.</div>';return}if(profile.app_role==='attendee'){staffUnassigned();return}staffShell();
}
function staffLogin(){document.querySelector('#staffBody').innerHTML=`<div class="formcard" style="max-width:560px;margin:auto"><div class="kicker" style="color:#0a78ae">Secure staff access</div><h2>Sign in to ISSSC</h2><p class="lead">Enter your authorised email. Supabase will send you a passwordless sign-in link.</p><form id="loginForm"><label class="field"><span>Email</span><input name="email" type="email" required></label><div id="loginMsg"></div><div class="actions"><button class="btn primary" type="submit">Send sign-in link</button></div></form></div>`;document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const email=new FormData(e.currentTarget).get('email');const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+'/#staff'}});document.querySelector('#loginMsg').innerHTML=error?`<div class="notice error">${esc(error.message)}</div>`:'<div class="notice ok">Sign-in link sent. Check your email and return here.</div>';};}
function staffUnassigned(){document.querySelector('#staffBody').innerHTML=`<div class="formcard" style="max-width:620px;margin:auto"><div class="kicker" style="color:#0a78ae">Staff access</div><h2>No staff role assigned</h2><p class="lead">Your account is signed in, but it currently has attendee access only. An ISSSC administrator must assign your staff role before this workspace opens.</p><div class="notice">Staff roles are assigned by an active ISSSC administrator. The designated platform-owner account is provisioned automatically on its first successful sign-in.</div><div class="actions"><button id="logout" class="btn secondary">Sign out</button></div></div>`;document.querySelector('#logout').onclick=logout;}

function staffShell(){
  const role=profile.app_role;
  const allowed={overview:true,sponsors:['admin','sponsor_manager'].includes(role),protocol:['admin','protocol','operations'].includes(role),finance:['admin','finance'].includes(role),content:['admin','content_manager','protocol','operations'].includes(role),eventadmin:role==='admin',users:role==='admin',audit:role==='admin'};
  if(!allowed[activeStaffTab])activeStaffTab='overview';
  const labels={overview:'Overview',sponsors:'Sponsors',protocol:'Protocol',finance:'Finance',content:'Event content',eventadmin:'Event setup',users:'User access',audit:'Audit log'};
  document.querySelector('#staffBody').outerHTML=`<div class="shell"><aside class="sidebar"><h3>Staff workspace</h3>${Object.entries(allowed).filter(([,v])=>v).map(([k])=>`<button class="sidebtn ${activeStaffTab===k?'active':''}" data-staff="${k}">${labels[k]}</button>`).join('')}<button class="sidebtn" id="logout">Sign out</button></aside><main class="content"><div class="toolbar"><div><div class="kicker" style="color:#0a78ae">${esc(role.replaceAll('_',' '))}</div><h2>${esc(profile.display_name||session.user.email)}</h2></div></div><div id="staffPanel"></div></main></div>`;
  document.querySelectorAll('[data-staff]').forEach(b=>b.onclick=()=>{activeStaffTab=b.dataset.staff;staffShell();});
  document.querySelector('#logout').onclick=logout;renderStaffPanel();
}
async function logout(){await sb.auth.signOut();session=null;profile=null;navigate('home');}

async function renderStaffPanel(){
  const el=document.querySelector('#staffPanel');el.innerHTML='<div class="loading">Loading…</div>';
  if(activeStaffTab==='overview')return staffOverview(el);
  if(activeStaffTab==='sponsors')return sponsorWorkspace(el);
  if(activeStaffTab==='protocol')return protocolWorkspace(el);
  if(activeStaffTab==='finance')return financeWorkspace(el);
  if(activeStaffTab==='content')return contentWorkspace(el);
  if(activeStaffTab==='eventadmin')return eventAdminWorkspace(el);
  if(activeStaffTab==='users')return userAccessWorkspace(el);
  if(activeStaffTab==='audit')return auditWorkspace(el);
}
async function staffOverview(el){const [{count:bookings},{count:attendees},{count:sponsors},{count:invoices}]=await Promise.all([sb.from('booking_requests').select('*',{count:'exact',head:true}).eq('status','submitted'),sb.from('attendees').select('*',{count:'exact',head:true}),sb.from('event_sponsors').select('*',{count:'exact',head:true}).eq('active',true),sb.from('invoices').select('*',{count:'exact',head:true})]);el.innerHTML=`<div class="statgrid"><div class="stat"><small>Awaiting review</small><strong>${bookings??0}</strong></div><div class="stat"><small>Attendees</small><strong>${attendees??0}</strong></div><div class="stat"><small>Active sponsors</small><strong>${sponsors??0}</strong></div><div class="stat"><small>Invoices</small><strong>${invoices??0}</strong></div></div><div class="grid two"><div class="card"><h3>Operational workflow</h3><p>Invitation → attendance request → Protocol acceptance → confirmed stay/travel/lift data → Finance readiness → invoice.</p></div><div class="card"><h3>Attendee app</h3><p>Published programme, venues, updates, biographies, table plans, documents and sponsor information all come from the same database.</p></div></div>`;}
async function userAccessWorkspace(el){const {data:users,error}=await sb.from('profiles').select('id,display_name,email,app_role,active,created_at').order('display_name');if(error){el.innerHTML=`<div class="notice error">${esc(error.message)}</div>`;return}const roles=['admin','sponsor_manager','protocol','finance','operations','content_manager','attendee','read_only'];el.innerHTML=`<div class="toolbar"><div><h2>User access</h2><p class="lead">Assign staff roles after a user has signed in once. The final active administrator cannot be removed.</p></div></div>${users?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>User</th><th>Role</th><th>Active</th><th></th></tr></thead><tbody>${users.map(u=>`<tr data-user-row="${u.id}"><td><b>${esc(u.display_name||'Unnamed user')}</b><div class="meta">${esc(u.email||'')}</div></td><td><select class="compact" data-role>${roles.map(r=>`<option value="${r}" ${u.app_role===r?'selected':''}>${esc(r.replaceAll('_',' '))}</option>`).join('')}</select></td><td><input data-active type="checkbox" ${u.active?'checked':''}></td><td><button class="btn small primary" data-save-user="${u.id}">Save</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No user accounts yet.</div>'}`;document.querySelectorAll('[data-save-user]').forEach(b=>b.onclick=async()=>{const row=b.closest('[data-user-row]');const role=row.querySelector('[data-role]').value;const active=row.querySelector('[data-active]').checked;b.disabled=true;const {error}=await sb.from('profiles').update({app_role:role,active}).eq('id',b.dataset.saveUser);if(error){alert(error.message);b.disabled=false;return}userAccessWorkspace(el);});}

