  document.querySelectorAll('[data-edit-sched]').forEach(b=>b.onclick=()=>editCoreContent('schedule',sched.find(x=>x.id===b.dataset.editSched),el));
  document.querySelectorAll('[data-edit-venue]').forEach(b=>b.onclick=()=>editCoreContent('venue',venues.find(x=>x.id===b.dataset.editVenue),el));
  document.querySelectorAll('[data-toggle-content]').forEach(b=>b.onclick=async()=>{const [table,id,val]=b.dataset.toggleContent.split(':');b.disabled=true;const {error}=await sb.from(table).update({published:val==='1'}).eq('id',id);if(error){alert(error.message);b.disabled=false;return}eventData=null;contentWorkspace(el);});
  document.querySelectorAll('[data-unassign]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this seating assignment?'))return;b.disabled=true;const {error}=await sb.from('seating_assignments').delete().eq('id',b.dataset.unassign);if(error){alert(error.message);b.disabled=false;return}contentWorkspace(el);});
