function staySegmentModal(attendeeId,stay,locations,rooms,rates,el,parent){
  const opts=(rows,val,label='name')=>`<option value="">Select</option>${(rows||[]).map(x=>`<option value="${x.id}" ${x.id===val?'selected':''}>${esc(x[label])}</option>`).join('')}`;
  const rateOpts=`<option value="">Select rate</option>${(rates||[]).filter(r=>r.charge_category==='accommodation').map(r=>`<option value="${esc(r.rate_code)}" ${r.rate_code===stay.rate_code?'selected':''}>${esc(r.rate_code)} · £${Number(r.unit_price).toFixed(2)} · ${esc(r.description)}${r.status!=='approved'?' · PROPOSED':''}</option>`).join('')}`;
  const m=modal(`<h2>Edit accommodation segment</h2><form id="stayForm"><div class="formgrid"><label class="field"><span>Assigned hotel</span><select name="location_id">${opts(locations,stay.location_id)}</select></label><label class="field"><span>Room type</span><select name="room_type_id">${opts(rooms,stay.room_type_id)}</select></label><label class="field"><span>Actual check-in</span><input name="actual_check_in" type="date" value="${esc(stay.actual_check_in||'')}"></label><label class="field"><span>Actual check-out</span><input name="actual_check_out" type="date" value="${esc(stay.actual_check_out||'')}"></label><label class="field"><span>Billing from</span><input name="billing_from" type="date" value="${esc(stay.billing_from||'')}"></label><label class="field"><span>Billing to</span><input name="billing_to" type="date" value="${esc(stay.billing_to||'')}"></label><label class="field wide"><span>Rate</span><select name="rate_code">${rateOpts}</select></label><label class="check"><input name="confirmed" type="checkbox" ${stay.protocol_confirmed?'checked':''}> Protocol confirmed</label></div><div class="notice warn">Non-standard package dates require an explicitly approved exception before this segment can be confirmed.</div><div class="formgrid"><label class="check"><input name="approved_exception" type="checkbox" ${stay.approved_exception?'checked':''}> Approved package exception</label><label class="field wide"><span>Exception reason</span><textarea name="exception_reason">${esc(stay.exception_notes||'')}</textarea></label></div><div id="stayMsg"></div><div class="actions"><button class="btn primary">Save segment</button></div></form>`);
  m.querySelector('#stayForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const approved=fd.get('approved_exception')==='on';if(approved!==!!stay.approved_exception||approved){await staffOpsApi('set_stay_exception',{stay_id:stay.id,approved,reason:fd.get('exception_reason')||null});}await staffOpsApi('save_stay',{stay_id:stay.id,location_id:fd.get('location_id')||null,room_type_id:fd.get('room_type_id')||null,actual_check_in:fd.get('actual_check_in')||null,actual_check_out:fd.get('actual_check_out')||null,billing_from:fd.get('billing_from')||null,billing_to:fd.get('billing_to')||null,rate_code:fd.get('rate_code')||null,protocol_confirmed:fd.get('confirmed')==='on'});m.remove();parent.remove();attendeeOperationsModal(attendeeId,el)}catch(err){m.querySelector('#stayMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
}
