async function eventAdminWorkspace(el){
  const {data:events,error}=await sb.from('events').select('*').order('event_year',{ascending:false});
  if(error){el.innerHTML=`<div class="notice error">${esc(error.message)}</div>`;return}
  const current=events?.find(x=>x.event_year===2027)||events?.find(x=>x.active)||events?.[0];
  const {data:configItems}=current?await sb.from('event_configuration_items').select('*').eq('event_id',current.id).order('item_code'):{data:[]};
  const billingState=current?.billing_configuration_confirmed?'<span class="pill green">Confirmed for issue</span>':'<span class="pill red">Not confirmed</span>';
  el.innerHTML=`<div class="toolbar"><div><h2>Event setup</h2><p class="lead">Administrator-only event configuration and controlled future-year rollover.</p></div><button class="btn secondary" id="rolloverEvent">Create future event</button></div>
  ${current?`<form id="eventConfigForm" class="formcard"><div class="formgrid"><div class="sectiontitle"><h3>${esc(current.name)}</h3><p>Year ${current.event_year} · ${current.active?'Active event':'Inactive event'}</p></div><label class="field wide"><span>Event name</span><input name="name" value="${esc(current.name)}"></label><label class="field"><span>Start date</span><input name="start_date" type="date" value="${esc(current.start_date||'')}" required></label><label class="field"><span>Midweek changeover</span><input name="midweek_changeover_date" type="date" value="${esc(current.midweek_changeover_date||'')}"></label><label class="field"><span>End date</span><input name="end_date" type="date" value="${esc(current.end_date||'')}" required></label><label class="field"><span>Attendance deadline</span><input name="attendance_deadline" type="date" value="${esc(current.attendance_deadline||'')}"></label><label class="field"><span>Invoice prefix</span><input name="invoice_prefix" value="${esc(current.invoice_prefix||'')}"></label><label class="field"><span>Default lift pass</span><input name="default_lift_pass_type" value="${esc(current.default_lift_pass_type||'')}"></label><label class="field"><span>Currency</span><input name="currency" value="${esc(current.currency||'GBP')}"></label><label class="field"><span>Payment terms (days)</span><input name="payment_terms_days" type="number" min="0" max="365" value="${esc(current.payment_terms_days??14)}"></label></div><div class="notice">The attendance deadline is optional and has not been inferred from historic events. Room inventory is also event-specific and is entered in Protocol.</div><div id="eventConfigMsg"></div><div class="actions"><button class="btn primary">Save event configuration</button></div></form>
  <form id="billingConfigForm" class="formcard" style="margin-top:20px"><div class="formgrid"><div class="sectiontitle"><h3>Invoice issuer & payment configuration</h3><p>${billingState} · These details appear on generated invoices and must be explicitly confirmed before any invoice can be issued.</p></div><label class="field wide"><span>Issuer name</span><input name="invoice_issuer_name" value="${esc(current.invoice_issuer_name||'')}"></label><label class="field wide"><span>Issuer address</span><textarea name="invoice_issuer_address">${esc(current.invoice_issuer_address||'')}</textarea></label><label class="field wide"><span>Legal / tax / charity details</span><textarea name="invoice_issuer_legal_details">${esc(current.invoice_issuer_legal_details||'')}</textarea></label><label class="field wide"><span>Payment instructions</span><textarea name="invoice_payment_instructions">${esc(current.invoice_payment_instructions||'')}</textarea></label><label class="field wide"><span>Invoice footer</span><textarea name="invoice_footer">${esc(current.invoice_footer||'')}</textarea></label><label class="check wide"><input name="billing_configuration_confirmed" type="checkbox" ${current.billing_configuration_confirmed?'checked':''}> I confirm these are the authorised issuer and payment details for ISSSC ${current.event_year}</label></div><div class="notice warn">Do not confirm this section until the current UKAFWSA legal/payment details have been checked. The system deliberately does not infer them from historic invoices.</div><div id="billingConfigMsg"></div><div class="actions"><button class="btn primary">Save billing configuration</button></div></form>`:'<div class="empty">No events found.</div>'}
  <h3 style="margin-top:26px">Configuration confirmations</h3><p class="lead">Items that the source material leaves for administrator confirmation are tracked here rather than silently inferred.</p>${configItems?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Code</th><th>Item</th><th>Status</th><th>Decision / evidence</th><th></th></tr></thead><tbody>${configItems.map(x=>`<tr><td><b>${esc(x.item_code)}</b></td><td>${esc(x.title)}<div class="meta">${esc(x.description)}</div></td><td>${x.status==='confirmed'?'<span class="pill green">Confirmed</span>':x.status==='not_applicable'?'<span class="pill">N/A</span>':'<span class="pill red">Pending</span>'}</td><td>${esc(x.decision||'—')}</td><td><button class="btn small secondary" data-config-item="${x.id}">Review</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No configuration items are recorded for this event.</div>'}
  <h3 style="margin-top:26px">Event history</h3>${events?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Year</th><th>Name</th><th>Dates</th><th>Rates</th><th>Billing config</th><th>Status</th></tr></thead><tbody>${events.map(e=>`<tr><td>${e.event_year}</td><td><b>${esc(e.name)}</b></td><td>${esc(e.start_date)} → ${esc(e.end_date)}</td><td>Event-specific</td><td>${e.billing_configuration_confirmed?'<span class="pill green">Confirmed</span>':'<span class="pill red">Not confirmed</span>'}</td><td>${e.active?'<span class="pill green">Active</span>':'Inactive'}</td></tr>`).join('')}</tbody></table></div>`:''}`;
  if(current){
    document.querySelector('#eventConfigForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await adminEventApi('update_event',{event_id:current.id,name:fd.get('name'),start_date:fd.get('start_date'),midweek_changeover_date:fd.get('midweek_changeover_date')||null,end_date:fd.get('end_date'),attendance_deadline:fd.get('attendance_deadline')||null,invoice_prefix:fd.get('invoice_prefix'),default_lift_pass_type:fd.get('default_lift_pass_type')||null,currency:fd.get('currency')||'GBP',payment_terms_days:Number(fd.get('payment_terms_days')||14)});document.querySelector('#eventConfigMsg').innerHTML='<div class="notice ok">Event configuration saved.</div>';eventData=null;}catch(err){document.querySelector('#eventConfigMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
    document.querySelector('#billingConfigForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await adminEventApi('update_billing_config',{event_id:current.id,invoice_issuer_name:fd.get('invoice_issuer_name')||null,invoice_issuer_address:fd.get('invoice_issuer_address')||null,invoice_issuer_legal_details:fd.get('invoice_issuer_legal_details')||null,invoice_payment_instructions:fd.get('invoice_payment_instructions')||null,invoice_footer:fd.get('invoice_footer')||null,billing_configuration_confirmed:fd.get('billing_configuration_confirmed')==='on'});document.querySelector('#billingConfigMsg').innerHTML='<div class="notice ok">Billing configuration saved.</div>';setTimeout(()=>eventAdminWorkspace(el),500);}catch(err){document.querySelector('#billingConfigMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
  }
  document.querySelectorAll('[data-config-item]').forEach(b=>b.onclick=()=>configurationItemModal(configItems.find(x=>x.id===b.dataset.configItem),el));
  document.querySelector('#rolloverEvent').onclick=()=>eventRolloverModal(current,el);
}
function configurationItemModal(item,el){
  if(!item)return;
  const m=modal(`<h2>${esc(item.item_code)} · ${esc(item.title)}</h2><p class="lead">${esc(item.description)}</p><form id="configItemForm"><div class="formgrid"><label class="field"><span>Status</span><select name="status"><option value="pending" ${item.status==='pending'?'selected':''}>Pending</option><option value="confirmed" ${item.status==='confirmed'?'selected':''}>Confirmed</option><option value="not_applicable" ${item.status==='not_applicable'?'selected':''}>Not applicable</option></select></label><label class="field wide"><span>Decision / evidence note</span><textarea name="decision">${esc(item.decision||'')}</textarea></label></div><div class="notice">Use this to record the authorised decision or evidence. The system will not infer a value from historic ISSSC data.</div><div id="configItemMsg"></div><div class="actions"><button class="btn primary">Save</button></div></form>`);
  m.querySelector('#configItemForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await adminEventApi('set_configuration_item',{item_id:item.id,status:fd.get('status'),decision:fd.get('decision')||null});m.remove();eventAdminWorkspace(el)}catch(err){m.querySelector('#configItemMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
}

function eventRolloverModal(source,el){
  if(!source){alert('No source event is available.');return}
  const y=Number(source.event_year)+1;
  const m=modal(`<h2>Create ISSSC ${y}</h2><p class="lead">This carries forward sponsors, contacts and the current rate-card structure. All carried rates are reset to <b>Proposed</b>. Room inventory is deliberately not copied because future capacity must be supplied by the administrator.</p><form id="rolloverForm"><div class="formgrid"><label class="field"><span>Event year</span><input name="event_year" type="number" value="${y}" min="${y}" required></label><label class="field"><span>Start date</span><input name="start_date" type="date" required></label><label class="field"><span>Changeover date</span><input name="midweek_changeover_date" type="date"></label><label class="field"><span>End date</span><input name="end_date" type="date" required></label><label class="field"><span>Attendance deadline</span><input name="attendance_deadline" type="date"></label></div><div class="notice warn">The new event will be created inactive. Activate it only when the public application has been rolled forward to that event year.</div><div id="rolloverMsg"></div><div class="actions"><button class="btn primary">Create future event</button></div></form>`);
  m.querySelector('#rolloverForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await adminEventApi('rollover',{source_event_id:source.id,event_year:fd.get('event_year'),start_date:fd.get('start_date'),midweek_changeover_date:fd.get('midweek_changeover_date')||null,end_date:fd.get('end_date'),attendance_deadline:fd.get('attendance_deadline')||null,make_active:false});m.remove();eventAdminWorkspace(el)}catch(err){m.querySelector('#rolloverMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
}
function editSponsorParticipationModal(row,el){
  const tiers=['','Entry','Race','Headline','Other'];
  const statuses=['invited','confirmed','declined','inactive'];
  const m=modal(`<h2>${esc(row.organisations?.organisation_name||'Sponsor')}</h2><form id="editSponsorForm"><div class="formgrid"><label class="field"><span>Sponsor tier</span><select name="sponsor_tier">${tiers.map(x=>`<option value="${esc(x)}" ${row.sponsor_tier===x?'selected':''}>${esc(x||'Not set')}</option>`).join('')}</select></label><label class="field"><span>Status</span><select name="sponsor_status">${statuses.map(x=>`<option value="${x}" ${row.sponsor_status===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="field"><span>Room allocation</span><input name="room_allocation" type="number" min="0" value="${row.room_allocation??0}"></label><label class="check"><input name="consolidated_invoice_requested" type="checkbox" ${row.consolidated_invoice_requested?'checked':''}> Consolidated invoice requested</label><label class="check"><input name="race_funding_sponsor" type="checkbox" ${row.race_funding_sponsor?'checked':''}> Race funding sponsor</label><label class="check"><input name="display_in_event_app" type="checkbox" ${row.display_in_event_app!==false?'checked':''}> Display in attendee app</label><label class="check"><input name="active" type="checkbox" ${row.active?'checked':''}> Active for this event</label></div><div id="editSponsorMsg"></div><div class="actions"><button class="btn primary">Save participation</button></div></form>`);
  m.querySelector('#editSponsorForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const {error}=await sb.from('event_sponsors').update({sponsor_tier:fd.get('sponsor_tier')||null,sponsor_status:fd.get('sponsor_status'),room_allocation:Number(fd.get('room_allocation')||0),consolidated_invoice_requested:fd.get('consolidated_invoice_requested')==='on',race_funding_sponsor:fd.get('race_funding_sponsor')==='on',display_in_event_app:fd.get('display_in_event_app')==='on',active:fd.get('active')==='on'}).eq('id',row.id);if(error){m.querySelector('#editSponsorMsg').innerHTML=`<div class="notice error">${esc(error.message)}</div>`;return}m.remove();eventData=null;sponsorWorkspace(el);};
}
function inventoryEditModal(eventId,row,locations,rooms,el,parent){
  const m=modal(`<h2>Edit room inventory</h2><form id="editInventoryForm"><div class="formgrid"><label class="field"><span>Location</span><select name="location_id" required>${(locations||[]).map(x=>`<option value="${x.id}" ${x.id===row.location_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field"><span>Room type</span><select name="room_type_id"><option value="">All / unspecified</option>${(rooms||[]).map(x=>`<option value="${x.id}" ${x.id===row.room_type_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field"><span>Rooms</span><input name="room_count" type="number" min="0" value="${row.room_count}" required></label><label class="field"><span>Beds</span><input name="bed_count" type="number" min="0" value="${row.bed_count??''}"></label><label class="field wide"><span>Notes</span><input name="notes" value="${esc(row.notes||'')}"></label><label class="check"><input name="active" type="checkbox" ${row.active?'checked':''}> Active</label></div><div id="editInventoryMsg"></div><div class="actions"><button class="btn primary">Save inventory</button></div></form>`);
  m.querySelector('#editInventoryForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const {error}=await sb.from('event_room_inventory').update({location_id:fd.get('location_id'),room_type_id:fd.get('room_type_id')||null,room_count:Number(fd.get('room_count')),bed_count:fd.get('bed_count')?Number(fd.get('bed_count')):null,notes:fd.get('notes')||null,active:fd.get('active')==='on'}).eq('id',row.id);if(error){m.querySelector('#editInventoryMsg').innerHTML=`<div class="notice error">${esc(error.message)}</div>`;return}m.remove();parent.remove();roomInventoryModal(eventId,el);};
}

async function render(route){route=route||((location.hash||'#home').slice(1));if(invitationToken&&route==='home')route='register';if(route==='event')return renderEvent();if(route==='register')return renderRegister();if(route==='mytrip')return renderMyTrip();if(route==='staff')return renderStaff();return renderHome();}

sb.auth.onAuthStateChange(async(_event,s)=>{session=s;const h=location.hash||'';if(h.includes('staff'))renderStaff();else if(h.includes('mytrip'))renderMyTrip();});
const {data:{session:initialSession}}=await sb.auth.getSession();session=initialSession;
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
render();
